/* G2 stock variant (2.2.6.10 native 0x5066ee..0x50678d): the mounting matrix is
 * Q14 int16, products accumulate in int32 and the result is shifted right 14. */
void inv_imu_remap_data(int16_t data[3], const int16_t mmatrix[9])
{
	uint8_t i;
	int32_t data_out[3] = { 0 };
	for (i = 0; i < 3; i++) {
		data_out[i] = data[0] * mmatrix[(i * 3) + 0];
		data_out[i] += data[1] * mmatrix[(i * 3) + 1];
		data_out[i] += data[2] * mmatrix[(i * 3) + 2];
	}
	data[0] = (int16_t)(data_out[0] >> 14);
	data[1] = (int16_t)(data_out[1] >> 14);
	data[2] = (int16_t)(data_out[2] >> 14);
}

static void wait_us(uint32_t us)
{
	uint64_t tt1, tt2;

	tt1 = inv_ict1531x_get_time_us();
	while (1) {
		tt2 = inv_ict1531x_get_time_us();
		if (tt2 > (tt1 + us))
			break;
	}
}

