{
	int rc = 0;

	rc |= inv_imu_edmp_mrm_enable_auto(s);

	return rc;
}

/* G2 stock variant (2.2.6.10 native 0x508ab4..0x508b59): before enabling auto
 * MRM, scale the MRM stability thresholds to the GAF magnetometer period
 * (10/20/40 ms); period 0 keeps the current ones, any other period is -1. */
int invn_mag_enable_automrm(inv_imu_device_t *s)
{
	int                           rc = 0;
	uint32_t                      mag_dt_us;
	inv_imu_edmp_mrm_parameters_t p;

	rc |= INV_IMU_READ_EDMP_SRAM(s, EDMP_GAF_CONFIG_MAG_DT_US, (uint8_t *)&mag_dt_us);
	rc |= inv_imu_edmp_mrm_get_parameters(s, &p);
	switch (mag_dt_us) {
	case 0:
		break;
	case 10000:
		p.mrm_coarse_stab_cnt_thr   = 100;
		p.mrm_fine_stab_cnt_thr     = 1;
		p.mrm_large_instability_cnt = 100;
		p.mrm_small_instability_cnt = 1500;
		p.mrm_stab_obs_window_cnt   = 100;
		break;
	case 20000:
		p.mrm_coarse_stab_cnt_thr   = 50;
		p.mrm_fine_stab_cnt_thr     = 1;
		p.mrm_large_instability_cnt = 50;
		p.mrm_small_instability_cnt = 750;
		p.mrm_stab_obs_window_cnt   = 50;
		break;
	case 40000:
		p.mrm_coarse_stab_cnt_thr   = 25;
		p.mrm_fine_stab_cnt_thr     = 1;
		p.mrm_large_instability_cnt = 25;
		p.mrm_small_instability_cnt = 375;
		p.mrm_stab_obs_window_cnt   = 25;
		break;
	default:
		return INV_ERROR;
	}
	rc |= inv_imu_edmp_mrm_set_parameters(s, &p);
	rc |= inv_imu_edmp_mrm_enable_auto(s);

	return rc;
}

