    // G2 stock variant (Apollo MAIN 0x58E6DE): older-revision flush without
    // the 5.1.0 queue/DMA/FIFO timeout counters. Returns success once the
    // last TX-complete flag is set, otherwise waits on TXCMP (when its
    // interrupt is enabled) or on the software queue and the FIFO BUSY flag.
    //
    am_hal_uart_state_t *pState = (am_hal_uart_state_t *) pHandle;
    uint32_t ui32Module = pState->ui32Module;

    if (pState->bLastTxComplete == true)
    {
        return AM_HAL_STATUS_SUCCESS;
    }

    if (UARTn(ui32Module)->IER_b.TXCMPMIM)
    {
        while (pState->bLastTxComplete == false)
        {
            ONE_BYTE_DELAY(pState);
